(() => {
  const $=s=>document.querySelector(s),dialog=$('#world-dialog'),scene=$('#world-scene'),rig=$('#photo-gallery-rig');
  const albums=[
    {city:'THE ORIGINAL TRILOGY',sky:'#6c3141',glow:'#ffb36f',badge:'Friendly Neighborhood Guardian',photos:[['spider1-action','Spider-Man (2002)','Peter Parker discovers his powers, learns the responsibility that comes with them, and faces the Green Goblin above the streets of New York.'],['spider2','Spider-Man 2 (2004)','Peter tries to balance ordinary life with protecting the city as Doctor Octopus becomes a formidable new threat.'],['spider3','Spider-Man 3 (2007)','A mysterious black suit brings new power and difficult choices. Peter faces a darker side of himself and a city full of enemies.']]},
    {city:'THE AMAZING SPIDER-MAN',sky:'#123967',glow:'#5bc8ff',badge:'Electric City Guardian',photos:[['amazing1','The Amazing Spider-Man (2012)','Andrew Garfield’s Peter Parker searches for answers about his past, meets Gwen Stacy, and confronts the Lizard.'],['amazing2','The Amazing Spider-Man 2 (2014)','A neon-lit New York becomes the setting for Peter’s battles with Electro and an increasingly complicated personal life.']]},
    {city:'PETER’S NEIGHBORHOOD',sky:'#112d4c',glow:'#ffc369',badge:'Queens Rooftop Guardian',photos:[['homecoming','Spider-Man: Homecoming (2017)','Peter tries to prove himself as a neighborhood hero while juggling school, friendships, and the Vulture’s dangerous technology.'],['farfromhome','Spider-Man: Far From Home (2019)','A European school trip takes a dramatic turn as Peter encounters Mysterio and extraordinary new threats.'],['nowayhome','Spider-Man: No Way Home (2021)','Three film worlds meet when a spell opens the door to familiar visitors from other realities.'],['brandnewday','Spider-Man: Brand New Day (2026)','Peter embraces life as a full-time Spider-Man while changes in his powers and a new threat test his limits.']]},
    {city:'THE ANIMATED SPIDER-VERSE',sky:'#46285d',glow:'#fd6aa5',badge:'Brooklyn Dimension Guardian',photos:[['into','Into the Spider-Verse (2018)','Miles Morales discovers that becoming Spider-Man means finding his own path. Bold color and comic-book energy define his world.'],['across','Across the Spider-Verse (2023)','Miles and Gwen cross into a kaleidoscope of different art styles and Spider-heroes, where every universe has its own visual identity.']]}
  ];
  const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;let world=null,found=new Set(),earned=new Set(),selected=0,angle=0,target=null,pitch=-4,auto=false,playMode=true,open=false,last=0,drag=null,dragged=false;
  try{const a=JSON.parse(localStorage.getItem('webverse-course-badges')||'[]');if(Array.isArray(a))earned=new Set(a.filter(x=>Number.isInteger(x)&&x>=0&&x<4))}catch{}
  const photos=()=>albums[world.index].photos;
  function badges(){document.querySelectorAll('[data-verse]').forEach(b=>{b.classList.toggle('world-complete',earned.has(+b.dataset.verse));b.title=earned.has(+b.dataset.verse)?'Rooftop course complete':''})}badges();
  function progress(complete=false){const count=found.size;$('#world-progress').textContent=count+' / 3 RECOVERED';$('#world-mission-title').textContent=complete?'COURSE COMPLETE':'ROOFTOP RUN';$('#world-mission-copy').textContent=complete?'Finish reached. All trackers recovered. Your course badge is unlocked.':count===3?'All trackers found. Reach the finish rooftop.':'Run, jump and swing. Collect three trackers and reach the finish.';if(complete){earned.add(world.index);try{localStorage.setItem('webverse-course-badges',JSON.stringify([...earned]))}catch{}badges()}$('#world-badge').classList.toggle('earned',earned.has(world.index));$('#world-reward-label').textContent=earned.has(world.index)?albums[world.index].badge:'WORLD BADGE / LOCKED';$('#world-replay').hidden=!complete;dialog.classList.toggle('mission-complete',complete)}
  function size(){const w=scene.clientWidth||900;rig.style.setProperty('--gallery-radius',Math.min(320,w*.3)+'px');rig.style.setProperty('--gallery-width',Math.min(370,Math.max(205,w*.39))+'px')}
  if(typeof ResizeObserver!=='undefined')new ResizeObserver(size).observe(scene);
  function render(){rig.style.setProperty('--gallery-angle',angle+'deg');rig.style.setProperty('--gallery-counter',-angle+'deg');rig.style.setProperty('--gallery-pitch',pitch+'deg')}
  function caption(){const p=photos()[selected];$('#gallery-count').textContent=String(selected+1).padStart(2,'0')+' / '+String(photos().length).padStart(2,'0');$('#world-story-title').textContent=p[1];$('#world-story-copy').textContent=p[2];document.querySelectorAll('[data-landmark]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.landmark===selected)));document.querySelectorAll('[data-gallery-thumb]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.galleryThumb===selected)))}
  function stopAuto(){auto=false;$('#gallery-auto').setAttribute('aria-pressed','false');$('#gallery-auto').textContent='Auto rotate'}
  function select(i){selected=(i+photos().length)%photos().length;const wanted=-selected*360/photos().length;target=angle+(((wanted-angle)%360+540)%360-180);if(reduced){angle=target;target=null;render()}stopAuto();caption()}
  function fullPhoto(){const p=photos()[selected];window.WebversePhoto.open('media/gallery/'+p[0]+'.jpg',p[1]+' studio artwork',p[1]+' · Studio artwork courtesy of Sony Pictures')}
  function album(){selected=0;angle=0;target=null;pitch=-4;stopAuto();$('#gallery-city-label').textContent=albums[world.index].city;$('#gallery-photo-nodes').innerHTML=photos().map((p,i)=>`<div class="gallery-photo-node" style="--gallery-node-angle:${i*360/photos().length}deg"><div class="gallery-photo-facing"><button class="gallery-photo-card" data-landmark="${i}" aria-label="${p[1]}: select photo; select again to enlarge" aria-pressed="${i===0}"><img src="media/gallery/${p[0]}.jpg" alt="${p[1]} studio artwork" width="2200" height="941" loading="lazy" draggable="false"><span>${p[1]}</span></button></div></div>`).join('');$('#gallery-thumbnails').innerHTML=photos().map((p,i)=>`<button data-gallery-thumb="${i}" aria-label="Select ${p[1]}" aria-pressed="${i===0}"><img src="media/gallery/${p[0]}.jpg" alt="" width="2200" height="941" loading="lazy" draggable="false"></button>`).join('');document.querySelectorAll('[data-landmark]').forEach(b=>b.onclick=()=>{if(dragged)return;const i=+b.dataset.landmark;if(i===selected)fullPhoto();else select(i)});document.querySelectorAll('[data-gallery-thumb]').forEach(b=>b.onclick=()=>select(+b.dataset.galleryThumb));size();render()}
  function setMode(play){playMode=play;$('#world-story .eyebrow').textContent=play?'ROOFTOP COURSE':'PHOTO STORIES';$('#course-panel').hidden=!play;scene.hidden=play;dialog.classList.toggle('viewing-photos',!play);$('#world-play-mode').classList.toggle('selected',play);$('#world-explore-mode').classList.toggle('selected',!play);$('#world-play-mode').setAttribute('aria-pressed',String(play));$('#world-explore-mode').setAttribute('aria-pressed',String(!play));window.dispatchEvent(new CustomEvent('webverse-course-mode',{detail:play}));if(play){stopAuto();$('#world-story-title').textContent='Your mission: cross the skyline.';$('#world-story-copy').textContent='Collect three gold trackers, use the blue anchors to swing across gaps, and reach the finish flag. Land on a new rooftop to unlock a checkpoint.'}else{size();caption()}}
  function enter(w){world=w;found=new Set();open=true;const a=albums[w.index];dialog.dataset.world=String(w.index);dialog.style.setProperty('--world-sky',a.sky);dialog.style.setProperty('--world-glow',a.glow);$('#world-era').textContent=w.subtitle;$('#world-heading').textContent=w.name;album();progress();setMode(true);dialog.showModal();document.documentElement.classList.add('world-is-open');window.dispatchEvent(new CustomEvent('webverse-world-open',{detail:true}))}
  $('#world-exit').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{open=false;drag=null;stopAuto();document.documentElement.classList.remove('world-is-open');window.dispatchEvent(new CustomEvent('webverse-world-open',{detail:false}));$('#verse-open').focus()});window.addEventListener('webverse-enter',e=>enter(e.detail));window.addEventListener('webverse-course-progress',e=>{if(!world||e.detail.world!==world.index)return;found=new Set(e.detail.trackers);progress(e.detail.complete)});$('#world-play-mode').onclick=()=>setMode(true);$('#world-explore-mode').onclick=()=>setMode(false);$('#world-replay').onclick=()=>{setMode(true);window.dispatchEvent(new CustomEvent('webverse-course-restart'))};$('#world-film-link').onclick=()=>{dialog.close();showPage('guide',true);$('#series').value=world.era;$('#search').value='';renderMovies()};
  $('#world-look-left').onclick=()=>select(selected-1);$('#world-look-right').onclick=()=>select(selected+1);$('#world-reset-view').onclick=()=>{pitch=-4;select(0)};$('#gallery-auto').onclick=()=>{auto=!auto;target=null;$('#gallery-auto').setAttribute('aria-pressed',String(auto));$('#gallery-auto').textContent=auto?'Pause rotation':'Auto rotate'};$('#gallery-fullscreen').onclick=fullPhoto;scene.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();select(selected+(e.key==='ArrowRight'?1:-1))}});
  scene.addEventListener('pointerdown',e=>{if(e.target.closest('.gallery-controls,.gallery-thumbnails'))return;drag={id:e.pointerId,x:e.clientX,y:e.clientY,sx:e.clientX,sy:e.clientY};dragged=false;stopAuto();target=null});scene.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;if(Math.hypot(e.clientX-drag.sx,e.clientY-drag.sy)>6){dragged=true;scene.setPointerCapture?.(e.pointerId)}angle+=(e.clientX-drag.x)*.32;pitch=Math.max(-15,Math.min(12,pitch-(e.clientY-drag.y)*.08));drag.x=e.clientX;drag.y=e.clientY;render()});function end(){if(drag&&dragged){const step=360/photos().length;selected=((Math.round(-angle/step)%photos().length)+photos().length)%photos().length;select(selected)}drag=null;setTimeout(()=>dragged=false,0)}scene.addEventListener('pointerup',end);scene.addEventListener('pointercancel',end);scene.addEventListener('lostpointercapture',()=>drag=null);
  function frame(now){requestAnimationFrame(frame);const dt=Math.min(Math.max((now-last)/1000,0),.05);last=now;if(!open||playMode||document.hidden||$('#photo-lightbox').open)return;if(target!==null){const d=target-angle;angle+=d*Math.min(1,dt*8);if(Math.abs(d)<.05){angle=target;target=null}}else if(auto&&!drag){angle-=dt*9;const step=360/photos().length,i=((Math.round(-angle/step)%photos().length)+photos().length)%photos().length;if(i!==selected){selected=i;caption()}}render()}requestAnimationFrame(frame);
})();
